## 反代

> 也可以通过gost
>
> ```bash
> # 开启 DoT 监听 (本地 853 -> 上游 1.1.1.1:853)
> # 只要把证书准备好
> ./gost -L "dot://:853?cert=cert.pem&key=key.pem" -F "dot://1.1.1.1:853"
> 
> # 开启 DoH 监听 (本地 443 -> 上游 1.1.1.1 DoH)
> ./gost -L "http2://:443?cert=cert.pem&key=key.pem" -F "https://1.1.1.1/dns-query"
> ```

**通用**

```nginx
stream {
    # 定义上游 DoT 服务器 (这里以 Cloudflare 为例)
    upstream dot_upstream {
        server 1.1.1.1:853;
        server 1.0.0.1:853;
    }

    server {
        listen 853 ssl; # DoT 标准端口

        # 你的证书路径
        ssl_certificate /etc/nginx/cert/yourdomain.crt;
        ssl_certificate_key /etc/nginx/cert/yourdomain.key;

        # 握手优化
        ssl_session_cache shared:SSL:10m;
        ssl_session_timeout 10m;

        # 反代设置
        proxy_pass dot_upstream;
        proxy_ssl on; # 如果上游也是 DoT，需要开启 SSL

        # 关键：开启 SNI，否则上游可能拒绝连接 (针对 Cloudflare/Google 等)
        proxy_ssl_server_name on;
        proxy_ssl_name one.one.one.one; 
    }
}

# --- DoH 配置 (Layer 7, Port 443) ---
http {
    # ... 其他标准 http 配置 ...

    server {
        listen 443 ssl http2; # 必须开启 http2，DoH 强依赖
        server_name dns.yourdomain.com;

        ssl_certificate /etc/nginx/cert/yourdomain.crt;
        ssl_certificate_key /etc/nginx/cert/yourdomain.key;

        location /dns-query {
            # 反代到 Cloudflare DoH
            proxy_pass https://1.1.1.1/dns-query;

            # 传递必要的 Header
            proxy_set_header Host cloudflare-dns.com;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

            # 保持连接
            proxy_http_version 1.1;
            proxy_set_header Connection "";

            # 同样需要处理上游 SNI
            proxy_ssl_server_name on;
            proxy_ssl_name cloudflare-dns.com;
        }
    }
}
```

**对于强验证**

```nginx
server {
    listen 443 ssl;
    server_name docker.yourdomain.com;

    # SSL 证书配置 (请替换为你自己的路径)
    ssl_certificate /etc/nginx/cert/docker.crt;
    ssl_certificate_key /etc/nginx/cert/docker.key;

    # 推荐的 SSL 优化参数
